   368  static Bool latm_dmx_process_event(GF_Filter *filter, const GF_FilterEvent *evt)
   369  {
   370          u32 i;
   371          GF_FilterEvent fevt;
   372          GF_LATMDmxCtx *ctx = gf_filter_get_udta(filter);
   373
   374          switch (evt->base.type) {
   375          case GF_FEVT_PLAY:
   376                  if (!ctx->is_playing) {
   377                          ctx->is_playing = GF_TRUE;
   378                          ctx->cts = 0;
   379                  }
   380                  if (! ctx->is_file) {
   381                          if (evt->play.start_range || ctx->initial_play_done) {
   382                                  ctx->latm_buffer_size = 0;
   383                                  ctx->resume_from = 0;
   384                          }
   385
   386                          ctx->initial_play_done = GF_TRUE;
   387                          return GF_FALSE;
   388                  }
   389                  ctx->start_range = evt->play.start_range;
   390                  ctx->in_seek = GF_TRUE;
   391                  ctx->file_pos = 0;
   392                  if (ctx->start_range) {
   393                          for (i=1; i<ctx->index_size; i++) {
   394                                  if (ctx->indexes[i].duration>ctx->start_range) {
   395                                          ctx->cts = (u64) (ctx->indexes[i-1].duration * GF_M4ASampleRates[ctx->sr_idx]);
   396                                          ctx->file_pos = ctx->indexes[i-1].pos;
   397                                          break;
   398                                  }
   399                          }
   400                  }
   401                  if (!ctx->initial_play_done) {
   402                          ctx->initial_play_done = GF_TRUE;
   403                          //seek will not change the current source state, don't send a seek
   404                          if (!ctx->file_pos)
   405                                  return GF_TRUE;
   406                  }
   407                  ctx->latm_buffer_size = 0;
   408                  ctx->resume_from = 0;
   409                  //post a seek
   410                  GF_FEVT_INIT(fevt, GF_FEVT_SOURCE_SEEK, ctx->ipid);
   411                  fevt.seek.start_offset = ctx->file_pos;
   412                  gf_filter_pid_send_event(ctx->ipid, &fevt);
   413
   414                  //cancel event
   415                  return GF_TRUE;
   416
   417          case GF_FEVT_STOP:
   418                  //don't cancel event
   419                  ctx->is_playing = GF_FALSE;
   420                  return GF_FALSE;
   421
   422          case GF_FEVT_SET_SPEED:
   423                  //cancel event
   424                  return GF_TRUE;
   425          default:
   426                  break;
   427          }
   428          //by default don't cancel event - to rework once we have downloading in place
   429          return GF_FALSE;
   430  }
