   510          while (1) {
   511                  pos = (u32) gf_bs_get_position(ctx->bs);
   512                  u8 latm_buffer[4096];
   513                  u32 latm_frame_size = 4096;
   514                  if (!latm_dmx_sync_frame_bs(ctx->bs,&ctx->acfg, &latm_frame_size, latm_buffer, NULL)) break;
   515
   516                  if (ctx->in_seek) {
   517                          u64 nb_samples_at_seek = (u64) (ctx->start_range * GF_M4ASampleRates[ctx->sr_idx]);
   518                          if (ctx->cts + ctx->dts_inc >= nb_samples_at_seek) {
