   547                                          ctx->prev_sap = GF_TRUE;
   548                                  } else {
   549                                          sap = GF_FILTER_SAP_NONE;
   550                                          ctx->prev_sap = GF_FALSE;
   551                                  }
   552                          }
   553                          gf_filter_pck_set_sap(dst_pck, sap);
